const trigger = $('Execute Workflow Trigger').first().json || {};
const allTxs = $input.all().map(item => item.json);

// 1. Resilient parameter extraction
let queryObj = {};
if (trigger.query) {
  if (typeof trigger.query === 'object') {
    queryObj = trigger.query;
  } else if (typeof trigger.query === 'string') {
    try { queryObj = JSON.parse(trigger.query); } catch(e) {}
  }
}

const startDate = String(trigger.startDate || queryObj.startDate || '').trim();
const endDate = String(trigger.endDate || queryObj.endDate || '').trim();
const filterCat = String(trigger.category || queryObj.category || '').toLowerCase().trim();
const filterVendor = String(trigger.vendor || trigger.merchant || queryObj.vendor || queryObj.merchant || '').toLowerCase().trim();
const filterType = String(trigger.type || queryObj.type || '').toLowerCase().trim(); // 'expense', 'income', 'all'
const limit = Math.min(100, Math.max(1, parseInt(trigger.limit || queryObj.limit || 30, 10)));

// Helper to parse dates uniformly
const parseDate = (raw) => {
  if (!raw) return '';
  const str = String(raw).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(str)) return str.slice(0, 10);
  const dmyMatch = str.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})/);
  if (dmyMatch) {
    return `${dmyMatch[3]}-${dmyMatch[2].padStart(2, '0')}-${dmyMatch[1].padStart(2, '0')}`;
  }
  const d = new Date(str);
  if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
  return '';
};

// 2. Filter active transactions
const activeTxs = allTxs.filter(t => {
  if (!t || t.amount === undefined || t.amount === '') return false;
  const rawType = String(t.type || '').toLowerCase().trim();
  if (rawType === 'deleted' || String(t.vendor || '').startsWith('[DELETED]')) return false;
  return true;
});

// 3. Apply search filters
const filtered = activeTxs.filter(t => {
  const dStr = parseDate(t.date || t.date_of_transaction || t.timestamp);
  if (startDate && dStr && dStr < startDate) return false;
  if (endDate && dStr && dStr > endDate) return false;

  if (filterCat) {
    const cat = String(t.category || '').toLowerCase();
    if (!cat.includes(filterCat)) return false;
  }

  if (filterVendor) {
    const v = String(t.vendor || '').toLowerCase();
    const desc = String(t.description || '').toLowerCase();
    if (!v.includes(filterVendor) && !desc.includes(filterVendor)) return false;
  }

  if (filterType) {
    const rawType = String(t.type || '').toLowerCase();
    const isCredit = rawType === 'credit' || rawType === 'income';
    if (filterType === 'expense' && isCredit) return false;
    if (filterType === 'income' && !isCredit) return false;
  }

  return true;
});

// 4. Sort newest first: date DESC, row_number DESC
filtered.sort((a, b) => {
  const da = parseDate(a.date || a.date_of_transaction || a.timestamp) || '1970-01-01';
  const db = parseDate(b.date || b.date_of_transaction || b.timestamp) || '1970-01-01';
  if (da !== db) return db.localeCompare(da);
  return (b.row_number || 0) - (a.row_number || 0);
});

if (filtered.length === 0) {
  let emptyMsg = 'No transactions found';
  if (filterCat) emptyMsg += ` for category "${filterCat}"`;
  if (filterVendor) emptyMsg += ` for vendor "${filterVendor}"`;
  if (startDate || endDate) emptyMsg += ` in the specified date range`;
  emptyMsg += '.';
  return {
    json: {
      response: emptyMsg,
      aggregates: { totalSpent: 0, totalIncome: 0, netFlow: 0, count: 0, categoryBreakdown: {}, topVendors: {} },
      transactions: [],
      totalCount: 0
    }
  };
}

// 5. Compute authoritative aggregates
let totalSpent = 0;
let totalIncome = 0;
const catBreakdown = {};
const vendorBreakdown = {};

filtered.forEach(t => {
  const rawAmt = String(t.amount || '').replace(/[^\d.]/g, '');
  const amt = parseFloat(rawAmt) || 0;
  const rawType = String(t.type || '').toLowerCase().trim();
  const isCredit = rawType === 'credit' || rawType === 'income';
  const cat = t.category || 'Other';
  const vendor = t.vendor || 'Unknown';

  if (isCredit) {
    totalIncome += amt;
  } else {
    totalSpent += amt;
    catBreakdown[cat] = (catBreakdown[cat] || 0) + amt;
    vendorBreakdown[vendor] = (vendorBreakdown[vendor] || 0) + amt;
  }
});

// Format top categories
const sortedCats = Object.keys(catBreakdown).sort((a, b) => catBreakdown[b] - catBreakdown[a]);
const catSummary = sortedCats.slice(0, 5).map(c => `• ${c}: ₹${Math.round(catBreakdown[c]).toLocaleString('en-IN')}`).join('\n');

// 6. Build LLM response
const limitedTxs = filtered.slice(0, limit);
let summaryString = `📊 TRANSACTION SUMMARY (${filtered.length} matching rows)\n`;
summaryString += `• Total Spent: ₹${Math.round(totalSpent).toLocaleString('en-IN')}\n`;
if (totalIncome > 0) {
  summaryString += `• Total Income: ₹${Math.round(totalIncome).toLocaleString('en-IN')}\n`;
  summaryString += `• Net Cashflow: ₹${Math.round(totalIncome - totalSpent).toLocaleString('en-IN')}\n`;
}
if (sortedCats.length > 0) {
  summaryString += `\n📁 Top Categories:\n${catSummary}\n`;
}
summaryString += `\n📋 Recent Transactions (Showing ${limitedTxs.length} of ${filtered.length}):\n`;

limitedTxs.forEach((tx, idx) => {
  const dStr = parseDate(tx.date || tx.date_of_transaction || tx.timestamp) || 'Unknown';
  const amt = parseFloat(String(tx.amount || '').replace(/[^\d.]/g, '')) || 0;
  const rawType = String(tx.type || '').toLowerCase();
  const sign = (rawType === 'credit' || rawType === 'income') ? '+' : '-';
  const txnId = tx.transactionId ? ` [ID: ${tx.transactionId}]` : '';
  summaryString += `${idx + 1}. ${dStr} | ${sign}₹${amt.toLocaleString('en-IN')} | ${tx.vendor || 'Unknown'} (${tx.category || 'Other'})${txnId}\n`;
});

return {
  json: {
    response: summaryString.trim(),
    aggregates: {
      totalSpent: Math.round(totalSpent * 100) / 100,
      totalIncome: Math.round(totalIncome * 100) / 100,
      netFlow: Math.round((totalIncome - totalSpent) * 100) / 100,
      count: filtered.length,
      categoryBreakdown: catBreakdown,
      topVendors: vendorBreakdown
    },
    transactions: limitedTxs.map(t => ({
      transactionId: t.transactionId || null,
      row_number: t.row_number || null,
      date: parseDate(t.date || t.date_of_transaction || t.timestamp),
      amount: parseFloat(String(t.amount || '').replace(/[^\d.]/g, '')) || 0,
      vendor: t.vendor,
      category: t.category,
      type: t.type,
      description: t.description || ''
    })),
    totalCount: filtered.length
  }
};
